@Test
public void practice_numDirectedTriangles_simpleAL() {
    HashSet<String> keysThree = new HashSet<String>();
    keysThree.add("A");
    keysThree.add("B");
    keysThree.add("C");
    Graph<String> g3 = new AdjacencyListGraph<String>(keysThree);
    g3.addEdge("A", "B");
    g3.addEdge("B", "C");
