@Test
public void practice_isStronglyConnected_basicAL() {
    Graph<String> g = Core.makeExampleALGraph();
    assertEquals(false, g.isStronglyConnected());
    HashSet<String> keys = new HashSet<String>();
    keys.add("x");
    keys.add("y");
    keys.add("z");
    Graph<String> g2 = new AdjacencyListGraph<String>(keys);
    g2.addEdge("x", "y");
    g2.addEdge("y", "z");
    g2.addEdge("z", "x");
    assertEquals(true, g2.isStronglyConnected());
    g2.removeEdge("z", "x");
    assertEquals(false, g2.isStronglyConnected());
    HashSet<String> single = new HashSet<String>();
    single.add("a");
    Graph<String> g3 = new AdjacencyListGraph<String>(single);
    assertEquals(true, g3.isStronglyConnected());
    m2points.add(2 * Core.m2weight);
}

@Test
public void practice_findUnknownBalloons_example0_AL() {
    HashSet<String> allBalloons = new HashSet<String>();
    allBalloons.add("A");
    allBalloons.add("B");
    allBalloons.add("C");
    allBalloons.add("E");
    Graph<String> g = new AdjacencyListGraph<String>(allBalloons);
    g.addEdge("A", "B");
    g.addEdge("B", "C");
    g.addEdge("B", "E");
    g.addEdge("C", "B");

    Set<String> confirmed = new HashSet<String>();
    confirmed.add("B");
    Set<String> unknown = g.findUnknownBalloons(confirmed, allBalloons);
    assertEquals(2, unknown.size());
    assertTrue(unknown.contains("A"));
    assertTrue(unknown.contains("E"));

    confirmed.clear();
    confirmed.add("C");
    unknown = g.findUnknownBalloons(confirmed, allBalloons);
    assertEquals(2, unknown.size());
    assertTrue(unknown.contains("A"));
    assertTrue(unknown.contains("E"));

    confirmed.clear();
    confirmed.add("A");
    confirmed.add("E");
    unknown = g.findUnknownBalloons(confirmed, allBalloons);
    assertEquals(2, unknown.size());
    assertTrue(unknown.contains("B"));
    assertTrue(unknown.contains("C"));

    m2points.add(3 * Core.m2weight);
}

@Test
public void practice_findUnknownBalloons_example1_AL() {
    HashSet<String> allBalloons = new HashSet<String>();
    for (String b : new String[]{"A","B","C","D","E","F","G","H","I"}) {
        allBalloons.add(b);
    }
    Graph<String> g = new AdjacencyListGraph<String>(allBalloons);
    g.addEdge("A", "B");
    g.addEdge("B", "C");
    g.addEdge("B", "E");
    g.addEdge("C", "B");
    g.addEdge("C", "D");
    g.addEdge("D", "A");
    g.addEdge("E", "F");
    g.addEdge("F", "E");
    g.addEdge("G", "H");
    g.addEdge("H", "G");

    Set<String> confirmed = new HashSet<String>();
    confirmed.add("A");
    Set<String> unknown = g.findUnknownBalloons(confirmed, allBalloons);
    assertEquals(5, unknown.size());
    assertTrue(unknown.contains("E"));
    assertTrue(unknown.contains("F"));
    assertTrue(unknown.contains("G"));
    assertTrue(unknown.contains("H"));
    assertTrue(unknown.contains("I"));

    confirmed.clear();
    confirmed.add("D");
    confirmed.add("F");
    confirmed.add("H");
    unknown = g.findUnknownBalloons(confirmed, allBalloons);
    assertEquals(1, unknown.size());
    assertTrue(unknown.contains("I"));

    confirmed.clear();
    confirmed.add("I");
    unknown = g.findUnknownBalloons(confirmed, allBalloons);
    assertEquals(8, unknown.size());

    m2points.add(3 * Core.m2weight);
}
